{
  "status": "answer",
  "summary": "To resolve stale stock levels for acme inventory‑api in production, run the warehouse resync job from the job runner; this converges stock within 10 minutes without requiring a cache flush during trading hours.",
  "recommended_action": {
    "action": "resync_job",
    "target": "inv-resync --tenant acme",
    "approval_required": false,
    "approver": ""
  },
  "claims": [
    {
      "text": "The stale stock levels can be fixed by triggering the warehouse resync job from the job runner.",
      "kind": "procedure",
      "citations": [
        {
          "evidence_id": "E3",
          "quote": "\"Trigger the warehouse resync job from the job runner (jobs run inv-resync --tenant acme). Stock converges within 10 minutes. No approval is needed.\""
        }
      ]
    },
    {
      "text": "Flushing the SKU cache during trading hours causes a cache stampede and checkout errors.",
      "kind": "cause",
      "citations": [
        {
          "evidence_id": "E4",
          "quote": "\"Do not flush the SKU cache between 06:00 and 22:00 UTC: a flush during trading hours causes a cache stampede on inventory-db (see INC-4702).\""
        },
        {
          "evidence_id": "E1",
          "quote": "\"Stock levels were stale for 40 minutes. On-call flushed the SKU cache at 14:00 UTC; the flush caused a cache stampede on inventory-db and 9 minutes of checkout errors.\""
        }
      ]
    }
  ],
  "gaps": [
    "The evidence does not specify whether any additional monitoring or alerting steps are required after running the resync job."
  ],
  "conflicts": []
}

